// @ts-check
/**
 * Builds the LaTeX and BibTeX parsers from their grammars.
 *
 * The parsers the editor uses are generated by @lezer/generator from the
 * `.grammar` files under features/source-editor (and the hand-written
 * tokenizers beside them). The generated files are not committed: they are
 * made here before `next build` and `next dev`, the way the original's
 * webpack plugin made them, so the grammar is the one source of truth.
 *
 * Type declarations are written beside the generated modules, so the
 * TypeScript code that imports a term by name is checked against the grammar.
 */
import { buildParserFile } from '@lezer/generator'
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..', 'features', 'source-editor')

const grammars = [
  { directory: join(root, 'lezer-latex'), name: 'latex', sources: ['tokens.mjs'] },
  { directory: join(root, 'lezer-bibtex'), name: 'bibtex', sources: ['tokens.mjs', 'highlight.mjs'] },
]

const force = process.argv.includes('--force')

/** The names a generated terms module exports, from its source. */
function termNames(terms) {
  const names = []
  for (const match of terms.matchAll(/^\s*(\w+) = \d+,?$/gm)) {
    names.push(match[1])
  }
  return names
}

for (const { directory, name, sources } of grammars) {
  const grammarPath = join(directory, `${name}.grammar`)
  const parserPath = join(directory, `${name}.mjs`)
  const termsPath = join(directory, `${name}.terms.mjs`)
  const parserTypesPath = join(directory, `${name}.d.mts`)
  const termsTypesPath = join(directory, `${name}.terms.d.mts`)

  const upToDate = () => {
    for (const output of [parserPath, termsPath, parserTypesPath, termsTypesPath]) {
      if (!existsSync(output)) {
        return false
      }
    }
    const built = Math.min(statSync(parserPath).mtimeMs, statSync(termsPath).mtimeMs)
    const inputs = [grammarPath, ...sources.map(source => join(directory, source))]
    return inputs.every(input => built > statSync(input).mtimeMs)
  }

  if (upToDate() && !force) {
    console.log(`${name} parser is up to date`)
    continue
  }

  const grammar = readFileSync(grammarPath, 'utf8')
  const { parser, terms } = buildParserFile(grammar, { fileName: grammarPath, moduleStyle: 'es' })
  writeFileSync(parserPath, parser)
  writeFileSync(termsPath, terms)
  writeFileSync(
    parserTypesPath,
    `// Generated beside ${name}.mjs by scripts/generate-latex-parser.mjs\nimport type { LRParser } from '@lezer/lr'\nexport declare const parser: LRParser\n`
  )
  writeFileSync(
    termsTypesPath,
    `// Generated beside ${name}.terms.mjs by scripts/generate-latex-parser.mjs\n` +
      termNames(terms)
        .map(term => `export declare const ${term}: number`)
        .join('\n') +
      '\n'
  )
  console.log(`${name} parser generated`)
}
